<script setup lang="ts">
import { ImagePlus, Plus, Check } from 'lucide-vue-next'
import { assetUrl, sanitizeHtml, normalizeHex, type Asset } from '@qinbian/shared'
const props=defineProps<{html:string;mediaIndex?:number;legacyId?:string|null}>(),emit=defineEmits<{update:[html:string]}>(),ctx=useQinbian()
const picker=ref(false),slotIndex=ref(0),width=ref(0),alt=ref(''),caption=ref(''),hasSlot=ref(false),imageSrc=ref(''),slotCount=ref(0),ratio=ref(false)
const value=ref(72),total=ref(100),unit=ref(''),label=ref(''),source=ref(''),color=ref('#247b80')
const pct=computed(()=>total.value>0?Math.round(value.value/total.value*1000)/10:0)
function parse(){const el=document.createElement('div');el.innerHTML=props.html;return el}
function slots(box:HTMLElement){return Array.from(box.querySelectorAll<HTMLElement>('section,img')).filter(el=>el.tagName==='IMG'||(el.firstElementChild?.tagName==='P'&&el.firstElementChild.textContent?.trim()==='＋'))}
function load(){if(!import.meta.client)return;const box=parse(),list=slots(box);slotCount.value=list.length;if(slotIndex.value>=list.length)slotIndex.value=0;const img=list[slotIndex.value];hasSlot.value=!!img;imageSrc.value=img?.tagName==='IMG'?(img.getAttribute('src')||''):'';width.value=Number(img?.getAttribute('width'))||parseFloat(img?.style.width||'')||0;alt.value=img?.getAttribute('alt')||'';caption.value=img?.parentElement?.tagName==='FIGURE'?img.parentElement.querySelector('figcaption')?.textContent||'':''
 ratio.value=props.legacyId==='G04'||!!box.querySelector('[data-ratio]')
 if(ratio.value){const root=box.querySelector<HTMLElement>('[data-ratio]'),ps=Array.from(box.querySelectorAll<HTMLParagraphElement>('p')),number=ps.find(p=>parseFloat(p.style.fontSize)===24),at=ps.indexOf(number!);value.value=Number(root?.dataset.ratioValue||number?.textContent?.replace(/[^\d.]/g,'')||72);total.value=Number(root?.dataset.ratioTotal||100);unit.value=root?.dataset.ratioUnit||'';label.value=root?.dataset.ratioLabel||ps[at+1]?.textContent||'';source.value=root?.dataset.ratioSource||'';const track=Array.from(box.querySelectorAll<HTMLElement>('section')).find(el=>el.style.height==='6px'&&el.firstElementChild?.tagName==='SECTION');color.value=normalizeHex((track?.firstElementChild as HTMLElement)?.style.backgroundColor||'')||'#247b80'}
}
onMounted(load);watch(()=>props.html,load);watch(()=>props.mediaIndex,n=>{slotIndex.value=n||0;load()});watch(slotIndex,load)
function changed(html:string){emit('update',sanitizeHtml(html))}
function choose(a:Asset){const box=parse(),list=slots(box),target=list[slotIndex.value];const figure=document.createElement('figure');figure.style.cssText='margin:0 auto 16px;';const img=document.createElement('img');img.src=assetUrl(a.id);img.setAttribute('data-asset-id',a.id);img.alt=a.name;img.style.cssText='max-width:100%;height:auto;display:block;margin:0 auto;';figure.append(img);if(target){const replace=target.parentElement?.tagName==='FIGURE'?target.parentElement:target;replace.replaceWith(figure)}else (box.firstElementChild||box).append(figure);picker.value=false;changed(box.innerHTML)}
function detachStyle(el:HTMLElement,prop:string){const custom=new Set((el.getAttribute('data-qb-custom-properties')||'').split(',').filter(Boolean));custom.add(prop);el.setAttribute('data-qb-custom-properties',[...custom].join(','));try{const bindings=JSON.parse(el.getAttribute('data-qb-styles')||'{}');delete bindings[prop];if(Object.keys(bindings).length)el.setAttribute('data-qb-styles',JSON.stringify(bindings));else el.removeAttribute('data-qb-styles')}catch{}}
function applyImage(){const box=parse(),target=slots(box)[slotIndex.value];if(!target||target.tagName!=='IMG')return;const old=target.parentElement?.tagName==='FIGURE'?target.parentElement:target,figure=(old.tagName==='FIGURE'?old.cloneNode(false):document.createElement('figure')) as HTMLElement,img=target.cloneNode(true) as HTMLImageElement;if(!figure.getAttribute('style'))figure.style.cssText='margin:0 auto 16px;';img.alt=alt.value;img.style.maxWidth='100%';img.style.height='auto';img.style.display='block';const oldWidth=Number(target.getAttribute('width'))||parseFloat((target as HTMLElement).style.width)||0;if(width.value!==oldWidth){detachStyle(img,'width');if(width.value>0){img.width=Math.min(2000,width.value);img.style.width=img.width+'px'}else{img.removeAttribute('width');img.style.removeProperty('width')}}figure.append(img);if(caption.value.trim()){const p=document.createElement('figcaption');p.style.cssText='margin:9px 0 0;font-size:12px;line-height:1.8;color:#657985;text-align:center;';p.textContent=caption.value;figure.append(p)}old.replaceWith(figure);changed(box.innerHTML);ctx.notify('图片设置已应用')}
function applyRatio(){if(total.value<=0||value.value<0||value.value>total.value){ctx.notify('总量需大于0，当前值应在0与总量之间',true);return}const box=parse(),root=(box.querySelector('[data-ratio]')||box.firstElementChild) as HTMLElement;if(root){root.dataset.ratio='true';root.dataset.ratioValue=String(value.value);root.dataset.ratioTotal=String(total.value);root.dataset.ratioLabel=label.value;root.dataset.ratioUnit=unit.value;root.dataset.ratioSource=source.value}const ps=Array.from(box.querySelectorAll<HTMLParagraphElement>('p')),number=ps.find(p=>parseFloat(p.style.fontSize)===24),at=ps.indexOf(number!);if(number)number.textContent=pct.value+'％';if(ps[at+1])ps[at+1]!.textContent=label.value;if(ps.at(-1))ps.at(-1)!.textContent=`${value.value}／${total.value}${unit.value?' '+unit.value:''}${source.value?'｜'+source.value:''}`;const track=Array.from(box.querySelectorAll<HTMLElement>('section')).find(el=>el.style.height==='6px'&&el.firstElementChild?.tagName==='SECTION');if(track?.firstElementChild){(track.firstElementChild as HTMLElement).style.width=pct.value+'%';if(normalizeHex((track.firstElementChild as HTMLElement).style.backgroundColor)!==normalizeHex(color.value)){detachStyle(track.firstElementChild as HTMLElement,'background-color');(track.firstElementChild as HTMLElement).style.backgroundColor=color.value}}changed(box.innerHTML);ctx.notify('数值与色条已同步')}
</script>
<template><div class="inspector-form"><template v-if="ratio"><h4>比例数据</h4><div class="two-fields"><label>当前值<input v-model.number="value" type="number" min="0" step="any"></label><label>总量<input v-model.number="total" type="number" min="0" step="any"></label></div><div class="ratio-readout"><strong>{{pct}}<small>％</small></strong><i><b :style="{width:Math.max(0,Math.min(100,pct))+'%',background:color}"/></i></div><label>指标名称<input v-model="label"></label><div class="two-fields"><label>单位<input v-model="unit"></label><label>色条配色<input v-model="color" type="color"></label></div><label>来源与说明<textarea v-model="source" rows="2"/></label><button class="btn full" @click="applyRatio">应用数值</button><hr></template><h4>图片与图注</h4><select v-if="slotCount>1" v-model.number="slotIndex" aria-label="选择图片位置"><option v-for="n in slotCount" :key="n" :value="n-1">第 {{n}} 张图片</option></select><img v-if="imageSrc" class="inspector-image" :src="imageSrc" alt="当前图片"><div v-else class="image-placeholder"><ImagePlus :size="24"/><span>{{hasSlot?'在这个位置放一张图片':'为组件加入图片'}}</span></div><button class="btn full" @click="picker=true"><ImagePlus :size="15"/>{{imageSrc?'替换图片':'从素材库选图'}}</button><template v-if="imageSrc"><label>显示宽度（0为自适应）<input v-model.number="width" type="number" min="0" max="2000"></label><label>图片描述<input v-model="alt"></label><label>图片图注<input v-model="caption"></label><button class="btn full" @click="applyImage"><Check :size="14"/>应用图片设置</button></template><AssetPicker v-if="picker" @close="picker=false" @select="choose"/></div></template>
